// Salida 1: consultar el dia mostrado | Salida 2: pedir lote de ese dia
const p = n => String(n).padStart(2, '0');
const h = new Date();
const hoy = `${h.getFullYear()}-${p(h.getMonth() + 1)}-${p(h.getDate())}`;
let sel = flow.get('fechaSel') || null;

switch (msg.topic) {
    case 'fecha': {
        const f = String(msg.payload).slice(0, 10);
        if (!/^\d{4}-\d{2}-\d{2}$/.test(f)) return null;
        sel = (f >= hoy) ? null : f;
        flow.set('fechaSel', sel);
        break;
    }
    case 'hoy':
        sel = null;
        flow.set('fechaSel', null);
        break;
    case 'lote':
        return [null, { fecha: sel || hoy, origen: 'dashboard' }];
    case 'refresco':
        // En modo historico los datos no cambian: no hace falta reconsultar
        if (sel) return null;
        break;
}
return [{ fecha: sel || hoy, enVivo: !sel }, null];

msg.payload = [
    { fecha: msg.fecha, sitio: 'huertolab' },
    { sort: { timestamp: 1 }, projection: { _id: 0 } }
];
return msg;

const VARS = ["humedad_pct", "temperatura_C", "conductividad_uScm", "ph", "nitrogeno_mgkg", "fosforo_mgkg", "potasio_mgkg"];
const R = flow.get('rangos') || {};
const dia = Array.isArray(msg.payload) ? msg.payload : [];
const p = n => String(n).padStart(2, '0');
const t = d => new Date(d.timestamp).getTime();
const inicio = new Date(msg.fecha + 'T00:00:00').getTime();

// Ultima lectura de cada sensor
const ult = {};
for (const d of dia) ult[d.sensor_id] = d;          // vienen ordenadas por hora
const sensores = Object.values(ult).sort((a, b) => a.sensor_id - b.sensor_id)
    .map(d => ({ sensor: d.sensor_id, t: t(d), valores: Object.fromEntries(VARS.map(k => [k, d[k]])) }));

// Series del dia por sensor
const ids = [...new Set(dia.map(d => d.sensor_id))].sort((a, b) => a - b);
const series = {};
for (const k of VARS) {
    series[k] = ids.map(id => ({ sensor: id,
        puntos: dia.filter(d => d.sensor_id === id && typeof d[k] === 'number').map(d => [t(d), d[k]]) }));
}

msg.payload = {
    fecha: msg.fecha, enVivo: msg.enVivo, total: dia.length, ahora: Date.now(),
    inicio, fin: inicio + 864e5, intervaloS: 300, rangos: R, sensores, series
};
return msg;

// Sin msg.fecha (inyeccion programada) = hoy en hora de Colombia (TZ del contenedor)
if (!msg.fecha) {
    const h = new Date(), p = n => String(n).padStart(2, '0');
    msg.fecha = `${h.getFullYear()}-${p(h.getMonth() + 1)}-${p(h.getDate())}`;
    msg.origen = 'programado';
}
msg.payload = [
    { fecha: msg.fecha, sitio: 'huertolab' },
    { sort: { timestamp: 1 }, projection: { _id: 0 } }
];
return msg;

// Prefijo MQTT por entorno: el simulador publica en otro prefijo y nunca
// contamina los lotes reales del laboratorio (docker-compose.sim.yml).
const PREFIJO = env.get('MQTT_PREFIJO') || 'uao/vermicompost/huertolab';
// Mismo formato que el emisor: timestamp,sensor_id,7 variables; hora local sin zona
const vars = ["humedad_pct", "temperatura_C", "conductividad_uScm", "ph", "nitrogeno_mgkg", "fosforo_mgkg", "potasio_mgkg"];
const p = n => String(n).padStart(2, '0');
const hora = t => { const d = new Date(t);
    return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`; };
const num = v => (typeof v === 'number' && Number.isInteger(v)) ? v.toFixed(1) : String(v);
const docs = Array.isArray(msg.payload) ? msg.payload : [];

const lineas = ['timestamp,sensor_id,' + vars.join(',')];
for (const d of docs) lineas.push([hora(d.timestamp), d.sensor_id, ...vars.map(v => num(d[v]))].join(','));
node.status({ fill: 'green', shape: 'dot', text: `${msg.fecha}: ${docs.length} lecturas (${msg.origen})` });
const csv = lineas.join('\n') + '\n';

// Solicitud del laboratorio: responde siempre por el topico aparte y sin retain
if (msg.origen === 'solicitud') {
    return [{ topic: PREFIJO + '/lote/solicitado', qos: 1, retain: false,
              payload: docs.length ? csv : `SIN_DATOS,${msg.fecha}` }, null];
}
// Programado (06:00 / 18:00) o boton del dashboard: topico de lote, con retain
const lote = { payload: csv, topic: PREFIJO + '/lote', qos: 1, retain: true };
const aviso = (msg.origen === 'dashboard')
    ? { payload: docs.length
          ? `Lote del ${msg.fecha} publicado (${docs.length} lecturas).`
          : `No hay lecturas el ${msg.fecha}; no se envió lote.` }
    : null;
return [docs.length ? lote : null, aviso];

// Node-RED NO sustituye ${VAR} dentro de un topico (se suscribe al texto literal),
// asi que el nodo escucha uao/vermicompost/+/solicitud y aqui se descarta lo que no sea de este entorno.
const PREFIJO = env.get('MQTT_PREFIJO') || 'uao/vermicompost/huertolab';
if (msg.topic !== PREFIJO + '/solicitud') return null;
// Acepta "2026-10-22" o {"fecha": "2026-10-22", "id": "..."}
let f = msg.payload, id = null;
if (typeof f === 'object' && f !== null) { id = f.id || null; f = f.fecha; }
f = String(f || '').trim().slice(0, 10);
if (!/^\d{4}-\d{2}-\d{2}$/.test(f)) {
    node.warn('Solicitud con fecha invalida: ' + JSON.stringify(msg.payload));
    return null;
}
node.status({ fill: 'blue', shape: 'dot', text: 'solicitud ' + f });
return { fecha: f, origen: 'solicitud', solicitudId: id };

// Valida lo que manda el navegador y arma la llamada a la API interna del agente.
// La respuesta vuelve a TODOS los navegadores con la pagina abierta; cada uno
// muestra solo la de su chat_id y su id de pregunta (ver el ui-template).
const p = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const chat_id = String(p.chat_id || '');
const id = String(p.id || '');
const texto = String(p.texto || '').trim().slice(0, 500);
if (!/^[A-Za-z0-9_-]{8,64}$/.test(chat_id) || !/^[A-Za-z0-9]{1,40}$/.test(id) || !texto) {
    node.warn('Mensaje del chat descartado (formato invalido)');
    return null;
}
return {
    url: (env.get('AGENTE_URL') || 'http://agente:8200') + '/chat',
    headers: { 'Content-Type': 'application/json' },
    payload: { chat_id, texto },
    requestTimeout: 200000,      // el LLM en la Pi puede tardar; el agente corta a los 180 s
    chat: { chat_id, id }
};

// Traduce la respuesta HTTP del agente al formato del ui-template.
const c = msg.chat || {};
const s = msg.statusCode;
const d = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
let texto, ok = false, confirmar_s = null;
if (s === 200 && typeof d.respuesta === 'string') {
    texto = d.respuesta;
    ok = true;
    confirmar_s = Number.isFinite(d.confirmar_s) && d.confirmar_s > 0 ? d.confirmar_s : null;
    node.status({ fill: 'green', shape: 'dot', text: 'respondio ' + new Date().toLocaleTimeString() });
} else if (s === 400 || s === 413) {
    texto = 'No pude procesar ese mensaje (' + (d.error || 'formato no valido') + ').';
} else {
    // Conexion rechazada / nombre no resuelto (perfil "agente" apagado), tiempo agotado o 5xx
    texto = 'El asistente no está disponible en este momento. No se hizo ningún cambio en las válvulas. Intente de nuevo en unos minutos.';
    node.status({ fill: 'red', shape: 'ring', text: 'no disponible: ' + s });
    node.warn('Agente no disponible: ' + s + ' ' + String(msg.payload).slice(0, 200));
}
return { payload: { chat_id: c.chat_id, id: c.id, texto, ok, confirmar_s } };

// Audio grabado por el navegador (webm/ogg/mp4) -> servicio de voz (Whisper).
// Todo lo que sale mal vuelve al navegador como {ok:false, error} con un texto para la persona.
const b = msg.payload;
const MAX = 3 * 1024 * 1024;
if (!Buffer.isBuffer(b) || b.length < 500 || b.length > MAX) {
    msg.statusCode = 200;
    msg.headers = { 'Cache-Control': 'no-store' };
    msg.payload = { ok: false, error: (Buffer.isBuffer(b) && b.length > MAX)
        ? 'La grabación es demasiado larga. Hable menos de 30 segundos.'
        : 'No se recibió audio. Intente de nuevo.' };
    return [null, msg];
}
msg.url = (env.get('VOZ_URL') || 'http://voz:8300') + '/transcribir';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/octet-stream' };
msg.requestTimeout = 90000;      // Whisper en la Pi tarda unos segundos; el LLM no interviene aqui
return [msg, null];

// Traduce la respuesta del servicio de voz a lo que espera la pagina.
const s = msg.statusCode;
const d = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
let out;
if (s === 200 && typeof d.texto === 'string') {
    out = { ok: true, texto: d.texto };
    node.status({ fill: 'green', shape: 'dot', text: 'transcribio ' + new Date().toLocaleTimeString() });
} else if (s === 413) {
    out = { ok: false, error: 'La grabación es demasiado larga. Hable menos de 30 segundos.' };
} else if (s === 415) {
    out = { ok: false, error: 'No pude leer ese audio. Intente de nuevo o escriba su pregunta.' };
} else if (s === 503) {
    out = { ok: false, error: 'La voz todavía se está preparando (descargando los modelos). Escriba su pregunta por ahora.' };
} else {
    out = { ok: false, error: 'El servicio de voz no está disponible en este momento. Escriba su pregunta.' };
    node.status({ fill: 'red', shape: 'ring', text: 'no disponible: ' + s });
    node.warn('Voz no disponible: ' + s + ' ' + String(msg.payload).slice(0, 200));
}
msg.statusCode = 200;
msg.headers = { 'Cache-Control': 'no-store' };
msg.payload = out;
return msg;

// Texto de la respuesta del agente -> servicio de voz (Piper). Devuelve un WAV.
const p = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const texto = (typeof p.texto === 'string') ? p.texto.trim().slice(0, 2000) : '';
if (!texto) {
    msg.statusCode = 400;
    msg.headers = { 'Cache-Control': 'no-store' };
    msg.payload = { ok: false, error: 'texto vacio' };
    return [null, msg];
}
msg.url = (env.get('VOZ_URL') || 'http://voz:8300') + '/hablar';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { texto };
msg.requestTimeout = 90000;
return [msg, null];

const s = msg.statusCode;
if (s === 200 && Buffer.isBuffer(msg.payload) && msg.payload.length > 44) {
    msg.headers = { 'Content-Type': 'audio/wav', 'Cache-Control': 'no-store' };
    return msg;
}
// Sin voz la respuesta sigue escrita en pantalla: la pagina solo avisa que no pudo leerla.
node.warn('Voz no disponible para hablar: ' + s);
node.status({ fill: 'red', shape: 'ring', text: 'no disponible: ' + s });
msg.statusCode = 503;
msg.headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
msg.payload = { ok: false, error: 'voz no disponible' };
return msg;
